const { ShopifyClientError } = require('../errors');

const PAGES_QUERY = `
  query($cursor: String) {
    pages(first: 250, after: $cursor) {
      edges {
        node {
          id
          title
          handle
          bodySummary
          body
          templateSuffix
          createdAt
          updatedAt
          publishedAt
        }
      }
      pageInfo {
        hasNextPage
        endCursor
      }
    }
  }
`;

const PAGE_CREATE_MUTATION = `
  mutation pageCreate($page: PageCreateInput!) {
    pageCreate(page: $page) {
      page {
        id
        title
        handle
      }
      userErrors {
        field
        message
      }
    }
  }
`;

const PAGE_UPDATE_MUTATION = `
  mutation pageUpdate($id: ID!, $page: PageUpdateInput!) {
    pageUpdate(id: $id, page: $page) {
      page {
        id
        title
        handle
      }
      userErrors {
        field
        message
      }
    }
  }
`;

const PAGE_DELETE_MUTATION = `
  mutation deleteOnlinePage($id: ID!) {
    pageDelete(id: $id) {
      deletedPageId
      userErrors {
        field
        message
      }
    }
  }
`;

function throwOnUserErrors(operation, userErrors) {
  if (!userErrors || userErrors.length === 0) {
    return;
  }

  throw new ShopifyClientError(`${operation} failed`, {
    code: 'SHOPIFY_USER_ERROR',
    details: {
      userErrors
    }
  });
}

function createPagesClient({ graphql }) {
  return {
    async listAll() {
      const pages = [];
      let hasNextPage = true;
      let cursor = null;

      while (hasNextPage) {
        const data = await graphql(PAGES_QUERY, { cursor });
        pages.push(...data.pages.edges.map((edge) => edge.node));
        hasNextPage = data.pages.pageInfo.hasNextPage;
        cursor = data.pages.pageInfo.endCursor;
      }

      return pages;
    },

    async create(pageData) {
      const data = await graphql(PAGE_CREATE_MUTATION, {
        page: {
          title: pageData.title,
          handle: pageData.handle,
          body: pageData.body,
          templateSuffix: pageData.templateSuffix,
          isPublished: pageData.publishedAt !== null
        }
      });

      throwOnUserErrors('Page create', data.pageCreate.userErrors);
      return data.pageCreate.page;
    },

    async update(pageId, pageData) {
      const data = await graphql(PAGE_UPDATE_MUTATION, {
        id: pageId,
        page: {
          title: pageData.title,
          body: pageData.body,
          templateSuffix: pageData.templateSuffix,
          isPublished: pageData.publishedAt !== null
        }
      });

      throwOnUserErrors('Page update', data.pageUpdate.userErrors);
      return data.pageUpdate.page;
    },

    async delete(pageId) {
      const data = await graphql(PAGE_DELETE_MUTATION, { id: pageId });
      throwOnUserErrors('Page delete', data.pageDelete.userErrors);
      return data.pageDelete.deletedPageId;
    }
  };
}

module.exports = {
  createPagesClient,
  PAGES_QUERY,
  PAGE_CREATE_MUTATION,
  PAGE_UPDATE_MUTATION,
  PAGE_DELETE_MUTATION
};
